it('wraps a non-Error rejection in an Error carrying the raw value as cause and rethrows the original', async () => {
  const reasons: unknown[] = ['non-error rejection', {code: 503, detail: 'upstream down'}, undefined];
  const outcomes = [];

  for (const rawRejection of reasons) {
    let receivedError: Error | undefined;
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw rawRejection;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
    const caught = await orchestrator.processMessage(createSession('hello')).catch((err: unknown) => err);
    outcomes.push({
      sameThrown: Object.is(caught, rawRejection),
      isError: receivedError instanceof Error,
      message: receivedError?.message,
      sameCause: Object.is(receivedError?.cause, rawRejection),
    });
  }

  expect(outcomes).toEqual([
    {sameThrown: true, isError: true, message: 'non-error rejection', sameCause: true},
    {sameThrown: true, isError: true, message: '[object Object]', sameCause: true},
    {sameThrown: true, isError: true, message: 'undefined', sameCause: true},
  ]);
});

